import {NODE,RES,ROLES,EVENTS,neighbors,moveCost,missionCheck,escapeCheck,activePlayers,ruleSet} from './core.js';
import {originLabel} from './campaign-ui.js';
import {guidanceFor} from './guide.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const action=(id,icon,title,sub,disabled=false)=>`<button class="play-action" id="${id}" ${disabled?'disabled':''}><span class="action-icon">${icon}</span><span><strong>${title}</strong><small>${sub}</small></span></button>`;
function destinationHTML(g,edge,control,recommended){const n=NODE[edge.to],walk=moveCost(g,edge.to,'foot'),rail=moveCost(g,edge.to,'rail'),footOnly=['mountain','foot'].includes(edge.type),enemy=g.pursuit?.pos===edge.to&&!g.pursuit.stunned;const mission=g.story?.missions.find(m=>!m.done&&m.nodes.includes(edge.to));return `<article class="destination-card ${recommended?'recommended':''}"><div class="destination-name"><strong>${n.name}</strong>${recommended?'<span>おすすめの一歩</span>':mission?'<span>任務の地点</span>':n.exit?'<span>脱出地点</span>':''}</div>${enemy?'<p class="destination-warning">追跡隊がいます。先に陽動を使いましょう。</p>':''}<div class="travel-buttons">${!footOnly?`<button data-quick-to="${n.id}" data-quick-mode="rail" ${!control||!g.ap||rail.error?'disabled':''}><strong>電車で行く</strong><small>${rail.error?(rail.error.includes('運転見合わせ')?'運休中':rail.error.includes('乗車券')?'乗車券が足りません':esc(rail.error)):`乗車券 ${rail.ticket}枚`}</small></button>`:''}<button data-quick-to="${n.id}" data-quick-mode="foot" ${!control||!g.ap||walk.error?'disabled':''}><strong>${edge.type==='mountain'?'山道を歩く':'歩いて行く'}</strong><small>${walk.error?(walk.error.includes('体力')?'体力が足りません':walk.error.includes('山装備')?'山装備が必要です':esc(walk.error)):`体力 −${walk.hp}`}</small></button></div></article>`}
export function actionScreenHTML(g,{control=true,online=null,localSlot=0,navigationTarget=null}={}){
 const p=g.players[g.turn],role=ROLES[p.role],n=NODE[p.pos],guide=guidanceFor(g,navigationTarget),mine=!online||localSlot===g.turn,ev=EVENTS[g.event],left=activePlayers(g),myPlayer=online?g.players[localSlot]:null;
 const localMissions=(g.story?.missions||[]).filter(m=>!m.done&&m.nodes.includes(p.pos)&&!m.requires?.some(id=>!g.story.missions.find(x=>x.id===id)?.done));
 const choices=neighbors(p.pos).sort((a,b)=>(b.to===guide.next?1:0)-(a.to===guide.next?1:0));
 const escape=n.exit?escapeCheck(g,n.exit):null;
 const utilities=g.ap&&control?`<div class="play-action-grid">${action('search-btn','⌕','探索する',g.searched.includes(p.pos)?'この場所は探索済み':`${RES[n.loot].label}を手に入れる`,g.searched.includes(p.pos))}${action('rest-btn','✚','休む','食料1 → 体力+4',g.resources.food<1)}${g.pursuit?action('hide-btn','◌','隠れる','追跡度を3下げる')+action('decoy-btn','⌁','陽動する','通信機1で追跡隊を止める',g.resources.signal<1):''}</div>`:'';
 const movement=g.ap&&control?`<div class="move-heading"><h3>移動する</h3><button data-screen="map">地図で見る ↗</button></div><div class="destination-list">${choices.slice(0,1).map(e=>destinationHTML(g,e,control,e.to===guide.next)).join('')}</div>${choices.length>1?`<details class="other-destinations"><summary>ほかの行き先を見る（${choices.length-1}）</summary>${choices.slice(1).map(e=>destinationHTML(g,e,control,e.to===guide.next)).join('')}</details>`:''}`:'';
 return `<div class="play-turn"><div><span class="turn-kicker">${control?(mine?'あなたの番':p.name+'の番'):'仲間の手番'}</span><h2>${esc(p.name)}<small> ${role.name}</small></h2></div><div class="remaining-rounds">残り<strong>${Math.max(0,g.limit-g.round+1)}</strong>ラウンド</div></div>
 <div class="play-position"><div><span>現在地</span><strong>${n.name}</strong></div><div class="play-vitals"><span>体力 <b>${p.hp}/8</b></span><button id="pursuit-info" ${!g.pursuit?'hidden':''}>追跡 <b>${g.pursuit?.heat||0}/10</b></button></div></div>
 <div class="play-supplies" aria-label="チームの共有物資">${Object.entries(RES).map(([k,v])=>`<div><span>${v.label}</span><strong style="color:${v.color}">${g.resources[k]}</strong></div>`).join('')}</div>
 ${!control?`<div class="play-wait"><strong>${myPlayer?.escaped?'脱出成功。いまは観戦中です。':esc(p.name)+'が操作しています。'}</strong><p>地図や任務を見ながら、次の作戦を相談しましょう。</p>${online?.isHost?'<button class="secondary" id="take-over">接続が切れた人の操作を引き継ぐ</button>':''}</div>`:`<section class="next-step ${guide.action==='end'?'step-complete':''}"><span>いま、やること</span><h3>${guide.title}</h3><p>${esc(guide.text)}</p>${navigationTarget?'<button class="cancel-navigation" id="cancel-navigation">この道案内をやめる ×</button>':''}</section>`}
 ${escape?.ok&&control?'<button class="mission-action escape-action" id="escape-btn">全員で脱出する →</button>':''}
 ${localMissions.map(m=>{const c=missionCheck(g,m.id);return `<div class="play-mission"><div><span>任務 ${m.id==='proof'?'A':m.id==='ally'?'B':'C'}</span><strong>${m.title}</strong></div>${!c.ok?`<p>${esc(c.reasons.join('。'))}</p>`:''}<button class="mission-action" data-perform-mission="${m.id}" ${!control||!g.ap||!c.ok?'disabled':''}>任務を実行（1行動）→</button></div>`}).join('')}
 ${guide.action==='move'?movement+utilities:utilities+movement}
 <details class="event-details"><summary>街の状況：${ev.name}</summary><p>${ev.text}</p></details>
 ${g.betrayal&&control&&mine?'<button class="betrayal-entry" id="betrayal-btn"><span>秘密の行動</span><small>自分だけの選択 ↗</small></button>':''}
 <div class="turn-footer"><div><span>${g.ap?'残りの行動':'行動完了'}</span><strong>${g.ap?g.ap+'回':'次の手番へ'}</strong></div><button id="end-turn" class="${g.ap?'finish-early':'finish-ready'}" ${!control?'disabled':''}>${left.some(x=>x.id>g.turn)?'次の人へ →':left.length===1?'次へ進む →':'次のラウンドへ →'}</button></div>`;
}
export function teamScreenHTML(g){return `<div class="screen-heading"><span>協力・状況確認</span><h2>チーム</h2><p>物資は全員で共有。各自の端末から、自分の手番に2回行動できます。</p></div><div class="team-cards">${g.players.map(p=>`<article><span class="team-avatar" style="color:${ROLES[p.role].color}">${p.id+1}</span><div><h3>${esc(p.name)} ${g.turn===p.id&&!p.escaped?'<span>行動中</span>':''}</h3><p>${p.escaped?'✓ 脱出済み':NODE[p.pos].name+' / 体力 '+p.hp+'/8'}</p><small>${ROLES[p.role].name} · ${esc(originLabel(p))}</small></div><button data-find="${p.id}">場所を見る</button></article>`).join('')}</div><div class="team-settings"><span>${ruleSet(g).name}</span><button id="team-story">今回の物語を読む</button></div>`}
export function compactBriefingHTML(g){const guide=guidanceFor(g),first=g.players[0];return `<span class="briefing-tag">独立初日 / 帰国作戦</span><h2 class="quick-brief-title">東京が独立。<br>さあ、故郷へ帰ろう。</h2><p>${esc(first.name)}は${esc(originLabel(first))}。近県から来ていた仲間と、東京国からの脱出を目指します。</p><ol class="quick-rules"><li><b>1</b><div><strong>1人ずつ、2回行動</strong><span>行き先を押して移動。探索で物資を集めよう。</span></div></li><li><b>2</b><div><strong>3つの任務をクリア</strong><span>証明書と仲間を確保して、県外へ連絡。</span></div></li><li><b>3</b><div><strong>同じ出口に集まって帰国</strong><span>追跡されたら「隠れる」。体力が減ったら「休む」。</span></div></li></ol><div class="first-step"><span>最初の目標</span><strong>${NODE[guide.node].name} / ${guide.label}</strong><small>画面の「いま、やること」が道案内します。</small></div><button class="primary" id="briefing-close"><span>ゲームをはじめる</span><span>→</span></button>`}
